{
  "name": "Sacher电动可调谐激光器",
  "name_en": "Sacher motorized tunable laser",
  "manufacturer": "Sacher Lasertechnik",
  "description": "这是一种通过电机驱动内部调谐机构来改变输出波长的可调谐激光器。设备可按设定波长或扫描速度进行调谐，常用于激光光谱、波长扫描、光学器件表征以及实验中激光波长的精细调整。",
  "description_en": "This is a tunable laser whose output wavelength is adjusted by a motor-driven internal tuning mechanism. It can tune to a target wavelength or scan at a defined rate, and is commonly used for laser spectroscopy, wavelength scanning, optical component characterization, and fine wavelength adjustment in laboratory experiments.",
  "tag_hints": [
    "tunable laser",
    "motorized wavelength tuning",
    "wavelength scanning",
    "laser spectroscopy",
    "optical characterization",
    "Maxon EPOS2 motion control"
  ],
  "actions": [
    {
      "action_name": "auto-calc_motor_acc",
      "description": "计算与波长扫描加速度对应的电机加速度参数。",
      "description_en": "Calculate the motor acceleration parameter corresponding to a wavelength scan acceleration."
    },
    {
      "action_name": "auto-set_position_profile",
      "description": "设置运动轮廓参数（速度、加速度、减速度）。",
      "description_en": "Set the motion profile parameters (velocity, acceleration, deceleration)."
    },
    {
      "action_name": "auto-set_velocity_nm_s",
      "description": "设置波长调谐速度。",
      "description_en": "Set the wavelength tuning velocity."
    },
    {
      "action_name": "auto-set_wavelength_m",
      "description": "设置输出波长。",
      "description_en": "Set the output wavelength."
    },
    {
      "action_name": "auto-stop_move",
      "description": "停止当前调谐运动。",
      "description_en": "Stop the current tuning motion."
    },
    {
      "action_name": "auto-update_motor_position",
      "description": "根据实测波长更新电机位置校准。",
      "description_en": "Update the motor position calibration using a measured wavelength."
    },
    {
      "action_name": "auto-set_default_settings",
      "description": "应用默认设备设置。",
      "description_en": "Apply the default device settings."
    },
    {
      "action_name": "auto-get_position_profile",
      "description": "获取运动轮廓参数（速度、加速度、减速度）。",
      "description_en": "Get the motion profile parameters (velocity, acceleration, deceleration)."
    },
    {
      "action_name": "auto-get_velocity_nm_s",
      "description": "获取波长调谐速度。",
      "description_en": "Get the wavelength tuning velocity."
    },
    {
      "action_name": "auto-get_state",
      "description": "获取设备状态。",
      "description_en": "Get the device state."
    },
    {
      "action_name": "auto-get_error_code",
      "description": "获取错误代码。",
      "description_en": "Get the error code."
    },
    {
      "action_name": "auto-get_wavelength_from_motor_pos",
      "description": "获取与电机位置对应的波长。",
      "description_en": "Get the wavelength corresponding to a motor position."
    },
    {
      "action_name": "auto-get_motor_pos_from_wavelength",
      "description": "获取与波长对应的电机位置。",
      "description_en": "Get the motor position corresponding to a wavelength."
    },
    {
      "action_name": "auto-get_wavelength_m",
      "description": "获取输出波长。",
      "description_en": "Get the output wavelength."
    }
  ]
}

